-- ELEMENT-TYPE: policy
-- ELEMENT-ID: POLICY:stats_fact_versions:lifecycle_reopen_update

CREATE POLICY lifecycle_reopen_update ON sync_fence.stats_fact_versions AS PERMISSIVE FOR UPDATE TO pitchlog_sync_right_fn_owner USING (tenant_id = NULLIF(pg_catalog.current_setting('app.tenant_id',true),'')::uuid AND session_user = 'pitchlog_app' AND completion_state='confirmed_ended' AND EXISTS(SELECT 1 FROM sync_fence.lifecycle_write_admissions a WHERE a.tenant_id=stats_fact_versions.tenant_id AND a.game_id=stats_fact_versions.game_id AND a.state='consumed' AND a.transaction_id=pg_catalog.pg_current_xact_id()::text AND a.action='reopen')) WITH CHECK (tenant_id = NULLIF(pg_catalog.current_setting('app.tenant_id',true),'')::uuid AND session_user = 'pitchlog_app' AND completion_state='confirmed_ended' AND EXISTS(SELECT 1 FROM sync_fence.lifecycle_write_admissions a WHERE a.tenant_id=stats_fact_versions.tenant_id AND a.game_id=stats_fact_versions.game_id AND a.state='consumed' AND a.transaction_id=pg_catalog.pg_current_xact_id()::text AND a.action='reopen'));
